/**
 * Blind quiz-answer verification.
 *
 * A quiz's answer key is generated by the same model that wrote the question,
 * and nothing downstream re-checks it: the structural contract only proves the
 * key names an existing option, not that it is the correct one. A wrong key
 * grades a correct student as wrong.
 *
 * The verifier is a CHEAP, independent solve: it sees the stem and the options
 * and nothing else - never the stored key or the explanation. The package
 * builds that blind projection, so the key cannot leak into the verifier
 * prompt, compares the returned choice set with the key, and feeds a
 * disagreement back into the bounded generation loop.
 *
 * Fail-open by construction: a missing, malformed or failed verdict is not a
 * disagreement. Only a usable answer that differs from the key drives a
 * corrective pass.
 */

import type { QuizQuestion } from '@openmaic/dsl';

/** One choice question with the answer key and explanation stripped. */
export interface QuizVerificationQuestion {
  id: string;
  type: 'single' | 'multiple';
  question: string;
  options: Array<{ value: string; label: string }>;
}

/** One verifier verdict: the option values the verifier chose. */
export interface QuizVerificationAnswer {
  id: string;
  answers: string[];
}

/**
 * Host-supplied blind solver. Returns null/undefined when verification could
 * not run; the package treats that as "no signal", never as a rejection.
 */
export type QuizAnswerVerifier = (
  questions: readonly QuizVerificationQuestion[],
) => Promise<readonly QuizVerificationAnswer[] | null | undefined>;

/** A key/solve mismatch that should be fed back into the loop. */
export interface QuizAnswerDisagreement {
  questionId: string;
  question: string;
  marked: string[];
  solved: string[];
}

/**
 * Project the generated quiz onto the blind verifier input.
 *
 * Short-answer questions are excluded (there is no key to verify) and so are
 * questions whose key is empty. Everything the solver must not see is dropped
 * here, not left to each host callback to remember.
 */
export function blindQuizQuestions(questions: readonly QuizQuestion[]): QuizVerificationQuestion[] {
  const blind: QuizVerificationQuestion[] = [];
  for (const question of questions) {
    if (question.type !== 'single' && question.type !== 'multiple') continue;
    const options = (question.options ?? []).filter(
      (option) => typeof option.value === 'string' && option.value.trim(),
    );
    const key = Array.isArray(question.answer) ? question.answer.filter(Boolean) : [];
    if (options.length === 0 || key.length === 0) continue;
    blind.push({
      id: question.id,
      type: question.type,
      question: question.question,
      options: options.map((option) => ({ value: option.value, label: option.label })),
    });
  }
  return blind;
}

function normalizedAnswerSet(values: readonly string[], allowed: ReadonlySet<string>): string[] {
  const unique = new Set<string>();
  for (const value of values) {
    if (typeof value === 'string' && allowed.has(value)) unique.add(value);
  }
  return [...unique].sort();
}

/**
 * Compare the blind solves with the stored keys. Any verdict for an unknown
 * question, an unknown option value, or the wrong cardinality is discarded
 * (fail-open); only a well-formed, differing answer counts.
 */
export function quizAnswerDisagreements(
  questions: readonly QuizQuestion[],
  answers: readonly QuizVerificationAnswer[] | null | undefined,
): QuizAnswerDisagreement[] {
  if (!answers || answers.length === 0) return [];
  const byId = new Map<string, string[]>();
  for (const answer of answers) {
    if (!answer || typeof answer.id !== 'string' || !Array.isArray(answer.answers)) continue;
    byId.set(answer.id, answer.answers);
  }

  const disagreements: QuizAnswerDisagreement[] = [];
  for (const question of questions) {
    if (question.type !== 'single' && question.type !== 'multiple') continue;
    const solvedRaw = byId.get(question.id);
    if (!solvedRaw) continue;
    const options = question.options ?? [];
    const allowed = new Set(options.map((option) => option.value));
    const solved = normalizedAnswerSet(solvedRaw, allowed);
    if (solved.length === 0) continue;
    if (question.type === 'single' && solved.length !== 1) continue;
    const marked = normalizedAnswerSet(
      Array.isArray(question.answer) ? question.answer : [],
      allowed,
    );
    if (marked.length === 0) continue;
    if (marked.length === solved.length && marked.every((value, i) => value === solved[i])) {
      continue;
    }
    disagreements.push({
      questionId: question.id,
      question: question.question,
      marked,
      solved,
    });
  }
  return disagreements;
}

/**
 * Corrective feedback for the next quiz attempt. It names the question, the
 * key's choice and the blind solve's choice, and asks for a full re-emit - the
 * quiz generator's contract is a complete JSON array per attempt.
 */
export function summarizeQuizAnswerDisagreements(
  disagreements: readonly QuizAnswerDisagreement[],
): string {
  return [
    'An independent blind solve (which did NOT see your answer key) disagreed with it:',
    ...disagreements.map(
      (finding) =>
        `- Question "${finding.questionId}": your key says ${finding.marked.join(
          ', ',
        )}, the blind solve chose ${finding.solved.join(', ')}.`,
    ),
    'Re-check each answer key against the question and its options. Fix wrong keys, and rewrite any question whose wording makes more than one option defensible. Then return the complete corrected JSON array.',
  ].join('\n');
}
